create extension if not exists "pgcrypto";
create table public.categorias (id uuid primary key default gen_random_uuid(), nombre text unique not null, orden int default 0, created_at timestamptz default now());
create table public.productos (id uuid primary key default gen_random_uuid(), nombre text not null, descripcion text, precio integer not null default 0, categoria_id uuid references public.categorias(id) on delete set null, imagen text, disponible boolean default true, destacado boolean default false, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.configuracion (id integer primary key default 1 check(id=1), nombre text, descripcion text, propuesta_nombre text default 'Sabores venezolanos hechos con cariño', frase_marca text default 'Un pedacito de Venezuela', descripcion_cultural text, mensaje_bienvenida text, direccion text, telefono text, whatsapp text, horario_semana text, horario_domingo text, instagram text, facebook text, hero_titulo text, hero_destacado text, hero_imagen text, historia text, historia_venezolana text, categorias_destacadas text default 'Arepas,Tequeños,Cachapas,Empanadas venezolanas,Pan de jamón,Golfeados', logo text, imagen_portada text, galeria_productos text default '[]', galeria_local text default '[]', galeria_promociones text default '[]', contenido_pagina jsonb default '{}'::jsonb, color_principal text default '#173a5e', color_secundario text default '#c94a3a', color_fondo text default '#fff8e8', color_destacado text default '#e7b83f', chatbot_nombre text default 'Cielito', chatbot_mensaje text default '¡Hola! Soy Cielito ☁️ Puedo ayudarte a conocer nuestros sabores venezolanos, productos disponibles y realizar tu pedido.', updated_at timestamptz default now());
create table public.promociones (id uuid primary key default gen_random_uuid(), titulo text not null, descripcion text, imagen text, fecha date default current_date, activa boolean default true, created_at timestamptz default now());
create table public.respuestas_chatbot (id uuid primary key default gen_random_uuid(), clave text unique not null, respuesta text not null, updated_at timestamptz default now());
alter table public.configuracion add column if not exists slogan text, add column if not exists tiktok text;
insert into public.categorias(nombre,orden) values ('Panadería',1),('Pastelería',2),('Tortas',3),('Arepas',4),('Desayunos',5),('Productos especiales',6) on conflict do nothing;
insert into public.configuracion(id,nombre,descripcion,direccion,telefono,whatsapp,horario_semana,horario_domingo,instagram,facebook,hero_titulo,hero_destacado) values (1,'Pedacito de Cielo','Panadería venezolana artesanal con sabores que reúnen a la familia.','Quillota 849, Viña del Mar','+56 9 0000 0000','56900000000','Lunes - Sábado: 09:00 AM a 06:00 PM','Domingos y feriados: 09:00 AM a 03:00 PM','https://www.instagram.com/pedacito.cielo1/','https://www.facebook.com/profile.php?id=100063548553528&ref=NONE_xav_ig_profile_page_web#','Un pedacito de Venezuela','en cada bocado.') on conflict(id) do nothing;
insert into public.respuestas_chatbot(clave,respuesta) values ('horarios','Atendemos de lunes a sábado de 09:00 AM a 06:00 PM y domingos y feriados de 09:00 AM a 03:00 PM.'),('direccion','Estamos en Quillota 849, Viña del Mar.'),('productos','Revisa el catálogo para conocer nuestros productos disponibles.'),('personalizados','Preparamos tortas personalizadas. Escríbenos por WhatsApp.'),('compra','Puedes reservar por WhatsApp y retirar en el local.') on conflict(clave) do nothing;
insert into storage.buckets(id,name,public) values ('imagenes','imagenes',true) on conflict(id) do update set public=true;
alter table public.categorias enable row level security;alter table public.productos enable row level security;alter table public.configuracion enable row level security;alter table public.promociones enable row level security;alter table public.respuestas_chatbot enable row level security;
create policy "Lectura pública categorías" on public.categorias for select using(true);create policy "Lectura pública productos" on public.productos for select using(true);create policy "Lectura pública configuración" on public.configuracion for select using(true);create policy "Lectura pública promociones" on public.promociones for select using(true);create policy "Lectura pública chatbot" on public.respuestas_chatbot for select using(true);
create policy "Admin categorías" on public.categorias for all to authenticated using(true) with check(true);create policy "Admin productos" on public.productos for all to authenticated using(true) with check(true);create policy "Admin configuración" on public.configuracion for all to authenticated using(true) with check(true);create policy "Admin promociones" on public.promociones for all to authenticated using(true) with check(true);create policy "Admin chatbot" on public.respuestas_chatbot for all to authenticated using(true) with check(true);
create policy "Imágenes públicas" on storage.objects for select using(bucket_id='imagenes');create policy "Admin sube imágenes" on storage.objects for insert to authenticated with check(bucket_id='imagenes');create policy "Admin edita imágenes" on storage.objects for update to authenticated using(bucket_id='imagenes');create policy "Admin elimina imágenes" on storage.objects for delete to authenticated using(bucket_id='imagenes');
